// source: types.go
/*
Package types holds the HTTP wire contract.

This package is the single source of truth for the shapes the frontend sees.
`make types` runs tygo over it to regenerate web/lib/api-types.ts, so a field
rename here becomes a TypeScript compile error there instead of a runtime
surprise during a live webinar.

Keep these boring: scalars, slices, maps and other types from this package.
No interfaces, no generics, no embedded structs from other packages.
*/

/**
 * Role decides what a participant may do inside a room. This is the entire
 * difference between a webinar and a meeting.
 */
export type Role = string;
export const RoleHost: Role = "host";
export const RolePanelist: Role = "panelist";
export const RoleAttendee: Role = "attendee";
export type WebinarStatus = string;
export const StatusScheduled: WebinarStatus = "scheduled";
export const StatusLive: WebinarStatus = "live";
export const StatusEnded: WebinarStatus = "ended";
export const StatusDraft: WebinarStatus = "draft";
export type WebinarKind = string;
export const KindLive: WebinarKind = "live";
export const KindSimulive: WebinarKind = "simulive";
export const KindRecurring: WebinarKind = "recurring";
/**
 * KindMeeting is a meeting: everyone admitted is on the stage, sized by PlanMeetingCap.
 */
export const KindMeeting: WebinarKind = "meeting";
export type ApprovalMode = string;
export const ApprovalAutomatic: ApprovalMode = "automatic";
export const ApprovalManual: ApprovalMode = "manual";
export type RegistrationState = string;
export const RegApproved: RegistrationState = "approved";
export const RegPending: RegistrationState = "pending";
export const RegDeclined: RegistrationState = "declined";
/**
 * RegUnverified is waiting on the same email-verification link as signup.
 * Not a host decision, and not a way into the room.
 */
export const RegUnverified: RegistrationState = "unverified";
/**
 * NotificationKind is why somebody is being told something.
 */
export type NotificationKind = string;
/**
 * NotifyApprovalRequested goes to the HOST: somebody is waiting for a decision.
 */
export const NotifyApprovalRequested: NotificationKind = "approval_requested";
/**
 * NotifyRegistrationApproved goes to the REGISTRANT, with their join link.
 */
export const NotifyRegistrationApproved: NotificationKind = "registration_approved";
/**
 * NotifyRegistrationDeclined goes to the REGISTRANT. Sent rather than silently
 * dropped: somebody who registered and hears nothing assumes they are coming.
 */
export const NotifyRegistrationDeclined: NotificationKind = "registration_declined";
/**
 * NotifyRegistrationConfirmed is auto-approve signup: they are in without a host review.
 */
export const NotifyRegistrationConfirmed: NotificationKind = "registration_confirmed";
/**
 *  NotifyReminder is one timed email reminder. A webinar has up to MaxReminders of them,
 * 	 * each ReminderOffsetMin before its start (WebinarOptions.Reminders), so the offset is
 * 	 * on the row and uniqueness is (kind, registration, offset). Replaced reminder_24h and
 * 	 * reminder_1h, which fixed the two times in the kind itself (migration 0052).
 */
export const NotifyReminder: NotificationKind = "reminder";
/**
 *  The same three things said on WhatsApp, which are separate kinds rather than
 * 	 * the same kinds on another channel. A host may well want both — an email with
 * 	 * a calendar file and a message on the phone the person will actually be
 * 	 * holding — and one kind per row is what lets the outbox guarantee one of each
 * 	 * per registration.
 */
export const NotifyWhatsAppConfirmed: NotificationKind = "wa_registration_confirmed";
/**
 *  NotifyWhatsAppReminder is the same timed reminder on WhatsApp: one template for every
 * 	 * time, chosen once by the host, with the `starts_in` merge field for "in 30 minutes".
 */
export const NotifyWhatsAppReminder: NotificationKind = "wa_reminder";
/**
 *  NotifyWhatsAppBroadcast is one recipient of one broadcast: the host's own
 * 	 * message, written once and queued per person, rather than anything this
 * 	 * application decided to send. It is not in WhatsAppReminderKinds because it has
 * 	 * no settings row — the template and its values belong to the broadcast.
 */
export const NotifyWhatsAppBroadcast: NotificationKind = "wa_broadcast";
/**
 *  NotifyWhatsAppDrip is one step of one person's sequence, queued when it comes
 * 	 * due rather than all at once — the next step's time is only known once the
 * 	 * previous one has actually gone. Also not in WhatsAppReminderKinds: the template
 * 	 * belongs to the step, and nothing about a webinar's clock may reschedule it.
 */
export const NotifyWhatsAppDrip: NotificationKind = "wa_drip";
/**
 *  NotifyReplayReady is the email that says the recording is up, with the link to
 * 	 * watch it. Sent when the host shares one, not when it finishes processing: a
 * 	 * replay link that arrives before anybody has decided to publish it would hand out
 * 	 * a recording the host has not looked at yet.
 */
export const NotifyReplayReady: NotificationKind = "replay_ready";
/**
 *  NotifyWhatsAppReplay is the same sentence on WhatsApp, and it is in
 * 	 * WhatsAppReminderKinds because it works the way the other automatic messages do:
 * 	 * the host picks an approved template for it once, and it is sent to the people
 * 	 * who registered for the webinar it belongs to.
 */
export const NotifyWhatsAppReplay: NotificationKind = "wa_replay";
/**
 *  NotifyWelcome is the one thank-you email a new account gets, from signup or a first
 * 	 * Google sign-in. Addressed by email, never user_id, so it is not a host alert; one
 * 	 * per address, enforced by a unique index (migration 0058).
 */
export const NotifyWelcome: NotificationKind = "welcome";
/**
 *  NotifyEmailVerify is the one-time link a password signup needs before it can sign in.
 * 	 * Addressed by email, like welcome, so it is not an in-app alert. Resending writes another
 * 	 * row; there is no unique index, unlike welcome.
 */
export const NotifyEmailVerify: NotificationKind = "email_verify";
/**
 *  NotifyPasswordReset is the one-time link that sets a new password. Addressed by email,
 * 	 * like the verification link, and for the same reason: whoever needs it cannot sign in.
 * 	 * Asking again writes another row and retires the previous link (migration 0088).
 */
export const NotifyPasswordReset: NotificationKind = "password_reset";
/**
 *  NotifyHostRequest is the note to the review inbox when an account asks to
 * 	 * host. Addressed to that inbox, with Reply-To set to the account, and
 * 	 * retried by the outbox like every other email.
 */
export const NotifyHostRequest: NotificationKind = "host_request";
/**
 *  The panelist's side of a webinar: added to the stage (with the stage link and a
 * 	 * calendar file), the start moved, the session cancelled. Addressed by email and tied to
 * 	 * no registration — a panelist signs in rather than holding a join key, so the link in
 * 	 * these is the same for every panelist and is not a credential. One invite per panelist
 * 	 * per webinar (migration 0070); updates and cancellations are one per change.
 */
export const NotifyPanelistInvited: NotificationKind = "panelist_invited";
export const NotifyPanelistRescheduled: NotificationKind = "panelist_rescheduled";
export const NotifyPanelistCancelled: NotificationKind = "panelist_cancelled";
/**
 *  NotifySessionRecap is the host's "Your AI recap" email after a session ends, and the
 * 	 * matching in-app alert. To the host only — attendees never get one. Like the replay,
 * 	 * it is ABOUT the session being over, so the outbox sends it for an ended webinar. One
 * 	 * per session: session_recaps.emailed_at (migration 0128).
 */
export const NotifySessionRecap: NotificationKind = "session_recap";
export const MaxReminders = 3;
export const MinReminderOffset = 1;
export const MaxReminderOffset = 30 * 24 * 60;
/**
 *  HostAlert is one in-app notification as a host's browser sees it.
 *  *
 *  * Carries the webinar's slug and topic rather than only an id, so the panel can render a
 *  * sentence and a link without a second request per row — a host with twenty alerts would
 *  * otherwise make twenty calls to find out what they were about.
 */
export interface HostAlert {
  id: string;
  kind: NotificationKind;
  webinarId: string; // slug, empty if the webinar is gone
  topic: string;
  subject: string;
  body: string;
  unread: boolean;
  createdAt: string;
}
/**
 * AlertsResponse is the notification panel's payload: the rows plus the badge count,
 * so opening the panel does not need a second request to know what the bell said.
 */
export interface AlertsResponse {
  alerts: HostAlert[];
  unread: number /* int */;
}
/**
 *  ApprovalsRequest is the batch decision: a set of registrations and one state for all of them.
 *  *
 *  * IDs rather than "everyone pending" because a host reviewing forty strangers approves some and
 *  * declines others, and an all-or-nothing endpoint makes them do it one request at a time. An
 *  * empty list is accepted and changes nothing, which is what a host who pressed the button with
 *  * no rows ticked meant.
 */
export interface ApprovalsRequest {
  ids: string[];
  state: RegistrationState;
}
/**
 * ApprovalsResponse reports what actually changed, not what was asked for. The two differ
 * when a row was already in the target state, or belonged to another webinar.
 */
export interface ApprovalsResponse {
  changed: number /* int */;
  notified: number /* int */;
  rows: RegistrantRow[];
}
export interface Person {
  id: string;
  name: string;
  title: string;
  org: string;
  initials: string;
  hue: string;
}
export interface AgendaItem {
  at: string;
  title: string;
  detail?: string;
}
export interface CustomQuestion {
  id: string;
  label: string;
  type: string; // short | select | checkbox
  required: boolean;
  options?: string[];
}
/**
 * WebinarOptions are the things a host decides while scheduling.
 */
export interface WebinarOptions {
  practiceSession: boolean;
  autoRecord: boolean;
  qAndA: boolean;
  /**
   * Polls used to be here, as a checkbox on the scheduling form. It is now
   * PollsEnabled in SessionControls: whether to poll the room is a decision made
   * during the session, next to chat and Q&A, and a host who ticked a box a week
   * earlier still had to be able to change their mind. Old rows keep a stray
   * "polls" key in their options JSON, which unmarshalling ignores.
   */
  attendeeChat: boolean;
  raiseHand: boolean;
  captions: boolean;
  multistream: boolean;
  postWebinarSurvey: boolean;
  /**
   *  EmailReminders is kept so old rows still resolve. The messages editor no
   * 	 * longer writes it; ResolveSlots reads it only when this webinar has no
   * 	 * reminder settings row. Missing means on.
   */
  emailReminders: boolean;
  /**
   *  WhatsAppReminders defaults FALSE, unlike its email counterpart, and the
   * 	 * asymmetry is deliberate: every WhatsApp message is charged to the host's own
   * 	 * Meta account, so spending their money on a webinar has to be something they
   * 	 * asked for. It also gates the confirmation message and not only the timed
   * 	 * reminders — one switch per webinar for "message my registrants on WhatsApp",
   * 	 * because a host turning it off does not mean "but keep sending one of them".
   */
  whatsappReminders: boolean;
  /**
   *  Reminders is when the timed reminders go, in minutes before the start, largest
   * 	 * first — [1440, 60] is "a day before and an hour before". Shared by email and
   * 	 * WhatsApp; each channel's switch above decides whether it sends them. At most
   * 	 * MaxReminders. Missing from a stored webinar means DefaultReminders; an empty list
   * 	 * means no timed reminders.
   */
  reminders: number /* int */[];
}
/**
 * SessionControls are the things a host flips *during* the session.
 * These live in Postgres rather than in a server's memory: a control has to
 * survive an API restart and it has to apply to someone who joins ten minutes
 * after it was set. "Attendees are hidden" is a property of the session.
 * They are also mirrored into LiveKit room metadata on every change, which is
 * how 500 browsers learn about a toggle without polling.
 */
export interface SessionControls {
  /**
   * HideAttendees is enforced at the SFU: attendee tokens are minted with
   * hidden=true, so an attendee is invisible to every other client rather
   * than merely filtered out of a list by our own JavaScript.
   */
  hideAttendees: boolean;
  muteOnEntry: boolean;
  allowUnmute: boolean;
  chatEnabled: boolean;
  qaEnabled: boolean;
  raiseHandEnabled: boolean;
  reactionsEnabled: boolean;
  /**
   * PollsEnabled decides whether the audience can be polled. Off hides the panel
   * for them entirely; the host still sees theirs, because writing the questions
   * is what you do before turning it on.
   */
  pollsEnabled: boolean;
  /**
   * CaptionsEnabled is the live-caption switch, and it is a CONTROL rather than
   * something the host's own browser remembers. Recognition runs against each
   * speaker's own microphone, so every publisher has to know captions are on or
   * only the person who pressed the button is ever transcribed. Initialised from
   * the scheduled Options.Captions when the webinar is created.
   */
  captionsEnabled: boolean;
  /**
   *  ServerCaptions says the captions are coming from the server (deploy/captions: a
   * 	 * LiveKit agent on the egress host transcribing the active speakers), so a speaker's
   * 	 * browser must NOT run its own on-device Whisper as well. True only while the host has
   * 	 * asked for server captions AND the agent has reported itself live in the room; a
   * 	 * dispatch nobody picked up, or an agent paused by its CPU guard, reads false and the
   * 	 * browsers fall back to local captions. Read-only here: set by
   * 	 * POST /api/host/webinars/{slug}/captions/server and by the agent, never by PATCH
   * 	 * /controls.
   */
  serverCaptions: boolean;
  /**
   *  AIEnabled is the room's "AI" switch: whether this session is in AI at all. On, a
   * 	 * transcript is captured for the AI recap even with captions (CaptionsEnabled, which is
   * 	 * only whether people SEE the lines) off — by the server caption agent in a transcript-only
   * 	 * mode, or silently by the speakers' browsers where no agent runs. Off at the end of the
   * 	 * session, no recap is written and nothing of the session goes to a model.
   * 	 *
   * 	 * On by default (webinars.ai_enabled, migration 0129), but only ever true when the host's
   * 	 * account has the ai feature: an account without it reads false here and AIAvailable
   * 	 * false, and the room shows no switch.
   */
  aiEnabled: boolean;
  /**
   * AIAvailable is whether the host's account has the ai feature, so the room knows to
   * show the switch. Read-only: it follows the account, not PATCH /controls.
   */
  aiAvailable: boolean;
  locked: boolean;
  /**
   * ChatDestination decides where an ATTENDEE's chat goes: to the whole room, or
   * to the stage only. The host owns it, which is the point — an attendee picking
   * their own audience is the thing this prevents.
   * It is a control rather than a per-message field so that it is one
   * authoritative value: set by the host through PATCH /controls, stored, and
   * mirrored into SFU room metadata, which is how 500 browsers learn about the
   * change without polling. Messages still carry the destination they were sent
   * with, so switching the setting never rewrites history.
   */
  chatDestination: ChatDestination;
}
/**
 * ChatDestination is the audience for a chat message.
 */
export type ChatDestination = string;
export const ChatToEveryone: ChatDestination = "everyone";
export const ChatToPanelists: ChatDestination = "panelists";
